diff --git a/src/__tests__/main/enterprise/dispatch.test.ts b/src/__tests__/main/enterprise/dispatch.test.ts
index 83435ebee..011a74ecb 100644
--- a/src/__tests__/main/enterprise/dispatch.test.ts
+++ b/src/__tests__/main/enterprise/dispatch.test.ts
@@ -24,0 +25,3 @@ import {
+	GROK_PRE_EFFECT_QUALIFIED_KINDS,
+	providerEffectRefusal,
+	qualifyProviderEffects,
@@ -25,0 +29,6 @@ import {
+import { createProcessSpawnAuthority } from '../../../main/enterprise/spawn-authority';
+import type {
+	ManagedEffect,
+	ManagedEffectBinding,
+} from '../../../shared/maestro-lib/managed/effects';
+import { fakeSpawnPort, tableEffects } from '../../helpers/managedSpawnPort';
@@ -472,0 +482,117 @@ describe('the Cue shell boundary', () => {
+
+/**
+ * Grok effect qualification (GT1-09-07, GT1-09-08). No Grok effect class is
+ * proven to ask before it executes, so every Grok effect reaching a managed
+ * desktop sink is refused `unavailable` BEFORE the composed authority is
+ * asked: the allow-everything table below is a declared double standing in
+ * for a producer, and its empty `asked` list is the proof that no decision
+ * (and so no receipt) exists for the refused effect. A passing case here
+ * proves the client-side refusal only, never a qualified Grok route.
+ */
+describe('Grok effect qualification at the managed effect sinks', () => {
+	const grok = (requestId = 'req-g'): ManagedEffectBinding => ({
+		leaseId: 'lease-g',
+		actor: { kind: 'human', id: 'ada' },
+		provider: 'grok',
+		threadId: null,
+		turnId: 'tab-g',
+		requestId,
+	});
+	const EFFECTS: Array<[string, ManagedEffect]> = [
+		['shell', { kind: 'command', command: 'curl https://x', cwd: '/p', argv: null }],
+		['file', { kind: 'file-change', paths: ['/p/a.ts'], cwd: '/p' }],
+		['network', { kind: 'permissions', permissions: { network: true } }],
+		['MCP', { kind: 'tool-call', tool: 'mcp__srv__fetch', input: { url: 'https://x' } }],
+		['user input', { kind: 'user-input', prompt: 'continue?' }],
+		['elicitation', { kind: 'elicitation', server: 'srv' }],
+	];
+	const allowAll = () => tableEffects(() => ({ decision: 'allow' }));
+	const signal = new AbortController().signal;
+
+	it('qualifies no Grok effect kind until exact-binary evidence exists', () => {
+		expect(GROK_PRE_EFFECT_QUALIFIED_KINDS).toEqual([]);
+	});
+
+	it.each(EFFECTS)(
+		'refuses a Grok %s effect unavailable before an allow-everything producer is asked',
+		async (_label, effect) => {
+			const inner = allowAll();
+			const decision = await qualifyProviderEffects(inner).decide(effect, grok(), signal);
+			expect(decision).toEqual({
+				decision: 'unavailable',
+				reason: expect.stringContaining(`A managed Grok ${effect.kind} effect is refused`),
+			});
+			expect((decision as { reason: string }).reason).toContain('GT1-11-12');
+			expect(inner.asked).toEqual([]);
+		}
+	);
+
+	it('refuses an unknown or unnamed Grok effect as unknown, never decided', async () => {
+		const inner = allowAll();
+		const qualified = qualifyProviderEffects(inner);
+		for (const effect of [
+			{ kind: 'other', method: 'hooks/run' },
+			{ kind: 'network-egress', host: 'x' } as unknown as ManagedEffect,
+		] as ManagedEffect[]) {
+			const decision = await qualified.decide(effect, grok(), signal);
+			expect(decision).toEqual({
+				decision: 'unavailable',
+				reason: expect.stringContaining(`unknown effect (${effect.kind})`),
+			});
+		}
+		expect(inner.asked).toEqual([]);
+	});
+
+	it('leaves other providers to the inner authority under its own id, so the refusal is not vacuous', async () => {
+		const inner = allowAll();
+		const qualified = qualifyProviderEffects(inner);
+		expect(qualified.authorityId).toBe('test-effects');
+		const effect = EFFECTS[0][1];
+		const binding = { ...grok(), provider: 'codex' };
+		expect(providerEffectRefusal(effect, binding)).toBeNull();
+		expect(await qualified.decide(effect, binding, signal)).toEqual({ decision: 'allow' });
+		expect(inner.asked).toEqual([{ effect, binding }]);
+	});
+
+	it('reads the provider from the lease binding: a replayed Grok approval request is refused every time', async () => {
+		const inner = allowAll();
+		const qualified = qualifyProviderEffects(inner);
+		const effect = EFFECTS[1][1];
+		const first = await qualified.decide(effect, grok('req-replay'), signal);
+		const replay = await qualified.decide(effect, grok('req-replay'), signal);
+		expect(first.decision).toBe('unavailable');
+		expect(replay).toEqual(first);
+		expect(inner.asked).toEqual([]);
+	});
+
+	it('holds the desktop port to the qualifier, with a composed producer and with none', async () => {
+		const deps = {
+			installation: { installationId: 'inst-1', runtimeId: 'desktop-1', processEpoch: 'e1' },
+			identity: { read: () => ({ status: 'none' }) as const },
+			host: { policy: () => ({ sources: [], policyRevision: 3 }) },
+			dispatch: { authority: fakeSpawnPort().authority },
+			now: () => 1_000_000,
+		};
+		const inner = allowAll();
+		const composed = createProcessSpawnAuthority({ ...deps, effects: inner });
+		const effect = EFFECTS[0][1];
+		expect((await composed.effects!.decide(effect, grok(), signal)).decision).toBe('unavailable');
+		expect(inner.asked).toEqual([]);
+		expect(
+			await composed.effects!.decide(effect, { ...grok(), provider: 'codex' }, signal)
+		).toEqual({ decision: 'allow' });
+
+		const bare = createProcessSpawnAuthority(deps);
+		const grokRefusal = await bare.effects!.decide(effect, grok(), signal);
+		expect((grokRefusal as { reason: string }).reason).toContain('A managed Grok command effect');
+		const codexRefusal = await bare.effects!.decide(
+			effect,
+			{ ...grok(), provider: 'codex' },
+			signal
+		);
+		expect(codexRefusal).toEqual({
+			decision: 'unavailable',
+			reason: expect.stringContaining('no per-effect authorization operation'),
+		});
+	});
+});
diff --git a/src/__tests__/main/permission-relay/relay-core.test.ts b/src/__tests__/main/permission-relay/relay-core.test.ts
index fac43a1d6..4d1a4cbf6 100644
--- a/src/__tests__/main/permission-relay/relay-core.test.ts
+++ b/src/__tests__/main/permission-relay/relay-core.test.ts
@@ -551,0 +552,121 @@ describe('permission-relay server AskUserQuestion round-trip', () => {
+	// GT1-09-07 / GT1-09-08: the relay's vocabulary is Claude Code's. A request
+	// from a managed Grok spawn is refused before the effect authority is asked
+	// and before the user is asked; the allow-everything table is a declared
+	// double, and its empty `asked` list is what shows no decision was made.
+	describe('a managed Grok spawn (GT1-09-08)', () => {
+		const allowAll = () => tableEffects(() => ({ decision: 'allow' }));
+		const composeGate = (effects = allowAll()) => {
+			const port = fakeSpawnPort({ effects });
+			const admissions = new Map<string, ReturnType<typeof fakeAdmission>>([
+				['sGk', fakeAdmission({ leaseId: 'lease-gk', provider: 'grok' })],
+				['sCc', fakeAdmission({ leaseId: 'lease-cc', provider: 'claude-code' })],
+			]);
+			const revoked = new Set<string>();
+			const gate = createRelayManagedGate({
+				port: () => port,
+				admissionOf: (sessionId) => admissions.get(sessionId) ?? null,
+				admissionLive: (sessionId) =>
+					revoked.has(sessionId)
+						? { ok: false, reason: 'the lease is revoked.' }
+						: admissions.has(sessionId)
+							? { ok: true }
+							: { ok: false, reason: 'no admission' },
+			});
+			return { gate, port, effects, revoked };
+		};
+		const request = (
+			toolName: string,
+			input: Record<string, unknown>,
+			overrides: Partial<PermissionRequest> = {}
+		): PermissionRequest => ({
+			requestId: 'rg',
+			token: 't',
+			sessionId: 'sGk',
+			tabId: 'tab-g',
+			toolName,
+			input,
+			createdAt: 0,
+			...overrides,
+		});
+		const refusedForGrok = {
+			managed: true,
+			decision: {
+				decision: 'unavailable',
+				reason: expect.stringContaining('a request from a managed Grok spawn is not mapped'),
+			},
+		};
+
+		it.each([
+			['shell', 'Bash', { command: 'curl https://x' }],
+			['file', 'Write', { file_path: '/p/a.ts', content: 'x' }],
+			['network', 'WebFetch', { url: 'https://x' }],
+			['MCP', 'mcp__srv__fetch', { url: 'https://x' }],
+			['unknown', 'grok_internal_tool', {}],
+		])(
+			'refuses a %s request unavailable before the effect authority is asked',
+			async (_l, tool, input) => {
+				const { gate, effects } = composeGate();
+				expect(
+					await gate.decide({ sessionId: 'sGk', tabId: 'tab-g' }, request(tool, input))
+				).toEqual(refusedForGrok);
+				expect(effects.asked).toEqual([]);
+			}
+		);
+
+		it('binds the provider to the spawn token, not the request: a misattributed or replayed approval stays refused', async () => {
+			const { gate, effects } = composeGate();
+			const misattributed = request('Bash', { command: 'ls' }, { sessionId: 'sCc' });
+			expect(await gate.decide({ sessionId: 'sGk' }, misattributed)).toEqual(refusedForGrok);
+			expect(await gate.decide({ sessionId: 'sGk' }, misattributed)).toEqual(refusedForGrok);
+			expect(effects.asked).toEqual([]);
+			// The same gate still asks the authority for a Claude Code spawn.
+			expect(await gate.decide({ sessionId: 'sCc' }, request('Bash', { command: 'ls' }))).toEqual({
+				managed: true,
+				decision: { decision: 'allow' },
+			});
+			expect(effects.asked.map((a) => a.binding.provider)).toEqual(['claude-code']);
+		});
+
+		it('denies a revoked Grok admission with the lease reason, and a standalone host is never a managed pass', async () => {
+			const { gate, port, effects, revoked } = composeGate();
+			revoked.add('sGk');
+			expect(await gate.decide({ sessionId: 'sGk' }, request('Read', { file_path: '/p' }))).toEqual(
+				{
+					managed: true,
+					decision: { decision: 'deny', reason: 'the lease is revoked.' },
+				}
+			);
+			port.setStanding('standalone');
+			expect(await gate.decide({ sessionId: 'sGk' }, request('Read', { file_path: '/p' }))).toEqual(
+				{
+					managed: false,
+				}
+			);
+			expect(effects.asked).toEqual([]);
+		});
+
+		it('through the relay server: denied with the Grok reason and the user is never asked', async () => {
+			const { token, cleanup } = registerSpawn({ sessionId: 'sGk', tabId: 'tab-g' });
+			const asked: PermissionRequest[] = [];
+			server.setOnRequest((req) => {
+				asked.push(req);
+				resolvePending(req.requestId, { behavior: 'allow' });
+			});
+			const { gate, effects } = composeGate();
+			server.setManagedGate(gate);
+			try {
+				const response = await relayRequest(token, 'mg1', 'Bash', { command: 'rm -rf /' });
+				expect(response.decision).toEqual({
+					behavior: 'deny',
+					message: expect.stringContaining(
+						'Refused under management: The permission relay reads Claude Code'
+					),
+				});
+				expect(asked).toEqual([]);
+				expect(effects.asked).toEqual([]);
+			} finally {
+				server.setManagedGate(null);
+				cleanup();
+			}
+		});
+	});
